    action_rows = reported_actions if isinstance(reported_actions, list) else []

    def ordered_structure_matches(
        rows: list[Any], row_keys: set[str], order: list[str] = expected_order
    ) -> bool:
        return (
            len(rows) == len(order)
            and all(isinstance(row, dict) and set(row) == row_keys for row in rows)
            and all(
                expected_customer in _normalize(_get(row, "customer"))
                for row, expected_customer in zip(rows, order)
            )
        )

    def normalized_bucket(value: Any) -> str:
        normalized = _normalize(value).replace(" days", "").replace(" day", "")
        normalized = normalized.replace(" plus", "")
        return "current" if normalized in {"current", "not past due"} else normalized

    def aging_structure_matches(rows: list[Any]) -> bool:
        return (
            len(rows) == len(expected_aging_order)
            and all(
                isinstance(row, dict) and set(row) == aging_row_keys for row in rows
            )
            and [normalized_bucket(_get(row, "bucket")) for row in rows]
            == [normalized_bucket(bucket) for bucket in expected_aging_order]
        )

    def aging_bucket_row(rows: list[Any], bucket: str) -> dict[str, Any]:
        expected_bucket = normalized_bucket(bucket)
        return next(
            (
                row
                for row in rows
                if isinstance(row, dict)
                and normalized_bucket(_get(row, "bucket")) == expected_bucket
            ),
            {},
        )

    def customer_row(rows: list[Any], customer: str) -> dict[str, Any]:
        token = _normalize(customer)
        return next(
            (
                row
                for row in rows
                if isinstance(row, dict)
                and token in _normalize(_get(row, "customer"))
            ),
            {},
        )

    control_status = _normalize(_get(mapping, "top_five_control_status"))
    control_status_matched = (
        any(token in control_status for token in ("exception", "error", "misstat", "does not tie", "doesn t tie"))
        and any(token in control_status for token in ("concentration", "top five", "top 5"))
    )
    control_action = _normalize(_get(mapping, "top_five_control_action"))
    control_action_matched = (
        any(token in control_action for token in ("correct", "update", "restate"))
        and any(token in control_action for token in ("concentration", "top five", "top 5"))
        and any(token in control_action for token in ("accounting", "reconcile", "tie"))
    )
    cash_control_status = _normalize(_get(mapping, "cash_forecast_control_status"))
    cash_control_status_matched = (
        any(token in cash_control_status for token in ("exception", "stale", "outdated", "does not tie", "doesn t tie"))
        and any(token in cash_control_status for token in ("v9", "june 26", "6 26"))
        and "retainage" in cash_control_status
        and any(token in cash_control_status for token in ("receipt", "cash", "timing"))
    )
    cash_control_action = _normalize(_get(mapping, "cash_forecast_control_action"))
    cash_control_action_matched = (
        any(token in cash_control_action for token in ("replace", "correct", "update"))
        and "non retainage" in cash_control_action
        and any(token in cash_control_action for token in ("june 30", "current"))
        and any(token in cash_control_action for token in ("accounting", "reconcile", "tie"))
    )
    rationale = _normalize(_get(mapping, "priority_rationale"))
    rationale_matched = (
        any(token in rationale for token in ("largest", "highest"))
        and any(token in rationale for token in ("balance", "exposure"))
        and re.search(r"\blow\b", rationale) is not None
        and any(token in rationale for token in ("validation", "close out", "closeout", "dispute"))
        and any(token in rationale for token in ("after july", "outside july", "hold", "august"))
    )
    release_condition = _normalize(_get(mapping, "priority_release_condition"))
    release_condition_matched = (
        "validation" in release_condition
        and any(token in release_condition for token in ("accept", "release", "resolve"))
        and any(token in release_condition for token in ("close out", "closeout", "support"))
    )
    accounting_treatment = _normalize(_get(mapping, "priority_accounting_treatment"))
    accounting_treatment_matched = (
        any(
            token in accounting_treatment
            for token in ("cash timing", "collection timing", "cash forecast", "treasury assumption")
        )
        and "revenue recognition" in accounting_treatment
        and "reserve" in accounting_treatment
        and "contract status" in accounting_treatment
    )

    criteria = [
        _weighted_numeric_criterion(mapping, "population__open_invoice_count", "The open-invoice population is complete", "open_invoice_count", gold["open_invoice_count"], weight=5, abs_tol=0.0, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "population__gross_open_ar", "Gross open AR agrees to the accounting population", "gross_open_ar", gold["gross_open_ar"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "workpaper__open_ar", "The AR workpaper balance is correct", "workpaper_open_ar", gold["workpaper_open_ar"], weight=5, category="controls"),
        _weighted_numeric_criterion(mapping, "workpaper__delta", "The workpaper-to-accounting difference is correct", "workpaper_delta", gold["workpaper_delta"], weight=5, category="controls"),
        _weighted_numeric_criterion(mapping, "population__open_retainage", "Open retainage exposure is correct", "open_retainage", gold["open_retainage"], weight=10),
        _weighted_numeric_criterion(mapping, "population__nonretainage_open_ar", "Open non-retainage AR is correct", "nonretainage_open_ar", gold["nonretainage_open_ar"], weight=10),
        _weighted_numeric_criterion(mapping, "aging__past_due_ar", "Past-due AR aged from contractual due date is correct", "past_due_ar", gold["past_due_ar"], weight=10),
        _weighted_numeric_criterion(mapping, "aging__ar_90_plus", "AR at least 90 days past contractual due date is correct", "ar_90_plus", gold["ar_90_plus"], weight=10),
        _weighted_numeric_criterion(mapping, "aging__schedule_delta", "The contractual-aging schedule ties to gross open AR", "aging_schedule_delta", gold["aging_schedule_delta"], weight=5, category="controls"),
        Criterion("aging_schedule__structure", "The contractual-aging schedule contains the five requested buckets in order with the requested fields", aging_structure_matches(aging_rows), f"contractual_aging_schedule={reported_aging!r}", category="controls", weight=1, semantic=False),
        _weighted_numeric_criterion(mapping, "concentration__reported_top_five", "The concentration reported in the controller notes is captured correctly", "reported_top_five_percent_of_ar", gold["reported_top_five_percent_of_ar"], weight=5, abs_tol=.00005, category="source_interpretation"),
        _weighted_numeric_criterion(mapping, "concentration__calculated_top_five_total", "The accounting top-five balance is correct", "calculated_top_five_total", gold["calculated_top_five_total"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "concentration__calculated_top_five_percent", "The accounting top-five concentration is correct", "calculated_top_five_percent_of_ar", gold["calculated_top_five_percent_of_ar"], weight=10, abs_tol=.00005),
        _weighted_numeric_criterion(mapping, "concentration__variance", "The reported-to-accounting concentration variance is correct", "top_five_variance", gold["top_five_variance"], weight=10, abs_tol=.00005, category="controls"),
        Criterion("concentration__control_status", "The material top-five concentration exception is identified", control_status_matched, "the reported concentration exception was identified" if control_status_matched else f"top_five_control_status={_get(mapping, 'top_five_control_status')!r}", category="controls", weight=5, semantic=False),
        Criterion("concentration__control_action", "The correction requires an accounting-population tie", control_action_matched, "the corrective action requires correction and an accounting tie" if control_action_matched else f"top_five_control_action={_get(mapping, 'top_five_control_action')!r}", category="controls", weight=10, semantic=False),
        _weighted_numeric_criterion(mapping, "nonretainage_concentration__top_five_total", "The top-five non-retainage customer balance is correct", "calculated_top_five_nonretainage_total", gold["calculated_top_five_nonretainage_total"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "nonretainage_concentration__top_five_percent", "The top-five concentration on non-retainage AR is correct", "calculated_top_five_nonretainage_percent_of_nonretainage", gold["calculated_top_five_nonretainage_percent_of_nonretainage"], weight=10, abs_tol=.00005),
        Criterion("nonretainage_concentration__structure", "The non-retainage concentration schedule contains the five largest customers in descending order with the requested fields", ordered_structure_matches(nonretainage_rows, nonretainage_row_keys, expected_nonretainage_order), f"top_five_nonretainage_schedule={reported_nonretainage!r}", category="controls", weight=1, semantic=False),
        _weighted_numeric_criterion(mapping, "overrides__population_total", "The five documented override balances total correctly", "override_population_total", gold["override_population_total"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "overrides__population_percent", "The five documented overrides' share of gross AR is correct", "override_population_percent_of_ar", gold["override_population_percent_of_ar"], weight=10, abs_tol=.00005),
        _weighted_numeric_criterion(mapping, "timing__july_exposure", "The override exposure timed for July is correct", "july_timed_override_exposure", gold["july_timed_override_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "timing__post_july_exposure", "The override exposure timed after July is correct", "post_july_timed_override_exposure", gold["post_july_timed_override_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "timing__untimed_retainage", "The retainage held without an accelerated collection date is correct", "untimed_retainage_exposure", gold["untimed_retainage_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "timing__bridge_delta", "The reported timing bridge delta is correct", "override_timing_bridge_delta", gold["override_timing_bridge_delta"], weight=5, category="controls"),
        _weighted_numeric_criterion(mapping, "confidence__high_july_exposure", "July-timed override exposure at High confidence is correct", "high_confidence_july_exposure", gold["high_confidence_july_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "confidence__medium_july_exposure", "July-timed override exposure at Medium confidence is correct", "medium_confidence_july_exposure", gold["medium_confidence_july_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "confidence__low_july_exposure", "July-timed override exposure at Low confidence is correct", "low_confidence_july_exposure", gold["low_confidence_july_exposure"], weight=10),
        _weighted_numeric_criterion(mapping, "confidence__below_high_july_exposure", "July-timed override exposure below High confidence is correct", "july_exposure_below_high_confidence", gold["july_exposure_below_high_confidence"], weight=10),
        _weighted_numeric_criterion(mapping, "confidence__bridge_delta", "The July confidence bridge ties to July-timed exposure", "july_confidence_bridge_delta", gold["july_confidence_bridge_delta"], weight=5, category="controls"),
        Criterion("override_schedule__structure", "The override schedule contains all five accounts in descending open-AR order with the requested fields", ordered_structure_matches(schedule_rows, schedule_row_keys), f"override_schedule={reported_schedule!r}", category="controls", weight=1, semantic=False),
        Criterion("cash_handoff__structure", "The v9-to-current cash handoff contains all five accounts in the requested order with the requested fields", ordered_structure_matches(cash_handoff_rows, cash_handoff_row_keys), f"cash_forecast_handoff_schedule={reported_cash_handoff!r}", category="controls", weight=1, semantic=False),
        _weighted_numeric_criterion(mapping, "cash_handoff__v9_july_gross", "The five-account gross July receipts in v9 are correct", "v9_july_gross_receipts", gold["v9_july_gross_receipts"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "cash_handoff__v9_july_retainage", "The retainage embedded in v9's five-account July receipts is correct", "v9_july_retainage_included", gold["v9_july_retainage_included"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "cash_handoff__v9_july_nonretainage", "The non-retainage portion of v9's five-account July receipts is correct", "v9_july_nonretainage_included", gold["v9_july_nonretainage_included"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "cash_handoff__june_30_additions", "The June 30 five-account population absent from v9 is correct", "june_30_additions_not_in_v9", gold["june_30_additions_not_in_v9"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "cash_handoff__current_supported_july", "The current supported five-account July non-retainage receipts are correct", "current_supported_july_nonretainage", gold["current_supported_july_nonretainage"], weight=10),
        _weighted_numeric_criterion(mapping, "cash_handoff__population_and_timing_adjustment", "The aggregate population-and-timing adjustment to v9 non-retainage is correct", "population_and_timing_adjustment", gold["population_and_timing_adjustment"], weight=10, category="reconciliation"),
        _weighted_numeric_criterion(mapping, "cash_handoff__net_july_correction", "The aggregate net correction to v9 July receipts is correct", "net_july_receipt_correction", gold["net_july_receipt_correction"], weight=10, category="decision_quality"),
        _weighted_numeric_criterion(mapping, "cash_handoff__handoff_delta", "The v9-to-current July cash handoff delta is correct", "cash_forecast_handoff_delta", gold["cash_forecast_handoff_delta"], weight=10, category="controls"),
        _weighted_numeric_criterion(mapping, "cash_handoff__reduction_percent", "The reduction from v9 gross July receipts is correct", "july_receipt_reduction_percent", gold["july_receipt_reduction_percent"], weight=10, abs_tol=.00005, category="decision_quality"),
        Criterion("cash_handoff__control_status", "The stale v9 population and retainage-timing exception is identified", cash_control_status_matched, "the v9 cash-timing exception was identified" if cash_control_status_matched else f"cash_forecast_control_status={_get(mapping, 'cash_forecast_control_status')!r}", category="controls", weight=10, semantic=False),
        Criterion("cash_handoff__control_action", "The cash handoff replaces v9 with current non-retainage timing tied to accounting", cash_control_action_matched, "the corrective handoff uses current non-retainage timing tied to accounting" if cash_control_action_matched else f"cash_forecast_control_action={_get(mapping, 'cash_forecast_control_action')!r}", category="decision_quality", weight=10, semantic=False),
        Criterion("action_queue__structure", "The action queue contains all five accounts in the schedule order with the requested fields", ordered_structure_matches(action_rows, action_row_keys), f"collection_action_queue={reported_actions!r}", category="controls", weight=1, semantic=False),
        _exact_text_criterion(mapping, "decision__priority_follow_up", "Columbia Biologics is correctly prioritized for follow-up", "priority_follow_up", ("Columbia Biologics", "Columbia Biologics, Inc."), weight=10),
        Criterion("decision__priority_rationale", "The priority rationale links the largest override to low-confidence disputed support and post-July timing", rationale_matched, "rationale contains the required balance, confidence, dispute, and timing facts" if rationale_matched else f"priority_rationale={_get(mapping, 'priority_rationale')!r}", category="decision_quality", weight=10, semantic=False),
        Criterion("decision__priority_release_condition", "The release condition requires accepted validation and close-out support", release_condition_matched, "release condition identifies accepted validation and close-out support" if release_condition_matched else f"priority_release_condition={_get(mapping, 'priority_release_condition')!r}", category="decision_quality", weight=5, semantic=False),
        Criterion("source_interpretation__priority_accounting_treatment", "The override remains a cash or collection timing judgment without changing revenue recognition, reserve, or contract status", accounting_treatment_matched, "accounting treatment preserves the documented scope" if accounting_treatment_matched else f"priority_accounting_treatment={_get(mapping, 'priority_accounting_treatment')!r}", category="source_interpretation", weight=5, semantic=False),
    ]

    aging_count_total = 0.0
    aging_open_total = 0.0
    aging_retainage_total = 0.0
    aging_nonretainage_total = 0.0
    aging_percent_total = 0.0
    for expected in expected_aging:
        bucket = expected["bucket"]
        token = _normalize(bucket).replace(" ", "_")
        row = aging_bucket_row(aging_rows, bucket)
        criteria.extend(
            [
                _weighted_numeric_criterion(row, f"aging_schedule__{token}__invoice_count", f"{bucket} invoice count is correct", "invoice_count", expected["invoice_count"], weight=3, abs_tol=0.0, category="reconciliation"),
                _weighted_numeric_criterion(row, f"aging_schedule__{token}__open_ar", f"{bucket} open AR is correct", "open_ar", expected["open_ar"], weight=10, category="reconciliation"),
                _weighted_numeric_criterion(row, f"aging_schedule__{token}__retainage_ar", f"{bucket} retainage is correct", "retainage_ar", expected["retainage_ar"], weight=10),
                _weighted_numeric_criterion(row, f"aging_schedule__{token}__nonretainage_ar", f"{bucket} non-retainage AR is correct", "nonretainage_ar", expected["nonretainage_ar"], weight=10),
                _weighted_numeric_criterion(row, f"aging_schedule__{token}__percent_of_ar", f"{bucket} share of gross AR is correct", "percent_of_ar", expected["percent_of_ar"], weight=5, abs_tol=.00005),
            ]
        )
        open_ar = _number(_get(row, "open_ar"))
        retainage_ar = _number(_get(row, "retainage_ar"))
        nonretainage_ar = _number(_get(row, "nonretainage_ar"))
        row_bridge_matched = (
            None not in (open_ar, retainage_ar, nonretainage_ar)
            and abs(retainage_ar + nonretainage_ar - open_ar) <= .02
        )
        criteria.append(
            Criterion(
                f"aging_schedule__{token}__bridge",
                f"{bucket} retainage and non-retainage tie to open AR",
                row_bridge_matched,
                f"open_ar={open_ar!r}; retainage={retainage_ar!r}; nonretainage={nonretainage_ar!r}",
                category="controls",
                weight=5,
                semantic=False,
            )
        )
        aging_count_total += _number(_get(row, "invoice_count")) or 0.0
        aging_open_total += open_ar or 0.0
        aging_retainage_total += retainage_ar or 0.0
        aging_nonretainage_total += nonretainage_ar or 0.0
        aging_percent_total += _number(_get(row, "percent_of_ar")) or 0.0

    aging_control_met = (
        _close(aging_count_total, gold["open_invoice_count"], abs_tol=0.0, rel_tol=0.0)
        and _close(aging_open_total, gold["gross_open_ar"], abs_tol=.02, rel_tol=0.0)
        and _close(aging_retainage_total, gold["open_retainage"], abs_tol=.02, rel_tol=0.0)
        and _close(aging_nonretainage_total, gold["nonretainage_open_ar"], abs_tol=.02, rel_tol=0.0)
        and _close(aging_percent_total, 1.0, abs_tol=.0001, rel_tol=0.0)
    )
    criteria.append(
        Criterion(
            "control__aging_schedule",
            "The five aging buckets reconcile invoice count, gross AR, retainage, non-retainage, and percentage to the population",
            aging_control_met,
            f"count={aging_count_total}; open_ar={aging_open_total}; retainage={aging_retainage_total}; nonretainage={aging_nonretainage_total}; percent={aging_percent_total}",
            category="controls",
            weight=10,
            semantic=False,
        )
    )

    nonretainage_schedule_total = 0.0
    for expected in expected_nonretainage:
        customer = expected["customer"]
        token = _normalize(customer).replace(" ", "_")
        row = customer_row(nonretainage_rows, customer)
        criteria.extend(
            [
                _weighted_numeric_criterion(row, f"nonretainage_concentration__{token}__amount", f"{customer} non-retainage AR is correct", "nonretainage_ar", expected["nonretainage_ar"], weight=10),
                _weighted_numeric_criterion(row, f"nonretainage_concentration__{token}__percent", f"{customer} share of non-retainage AR is correct", "percent_of_nonretainage", expected["percent_of_nonretainage"], weight=5, abs_tol=.00005),
            ]
        )
        nonretainage_schedule_total += _number(_get(row, "nonretainage_ar")) or 0.0
    nonretainage_schedule_control = _close(
        nonretainage_schedule_total,
        gold["calculated_top_five_nonretainage_total"],
        abs_tol=.02,
        rel_tol=0.0,
    )
    criteria.append(
        Criterion(
            "control__nonretainage_concentration_schedule",
            "The five non-retainage customer rows tie to the reported top-five non-retainage total",
            nonretainage_schedule_control,
            f"schedule_total={nonretainage_schedule_total}; expected={gold['calculated_top_five_nonretainage_total']}",
            category="controls",
            weight=10,
            semantic=False,
        )
    )

    schedule_open_total = 0.0
    schedule_july_total = 0.0
    schedule_post_july_total = 0.0
    schedule_retainage_total = 0.0
    schedule_confidence_july = {"high": 0.0, "medium": 0.0, "low": 0.0}
    for expected in expected_schedule:
        customer = expected["customer"]
        token = _normalize(customer).replace(" ", "_")
        row = customer_row(schedule_rows, customer)
        criteria.extend(
            [
                _weighted_numeric_criterion(row, f"override_schedule__{token}__open_ar", f"{customer} open AR is correct", "open_ar", expected["open_ar"], weight=10),
                _weighted_numeric_criterion(row, f"override_schedule__{token}__percent_of_ar", f"{customer} share of gross AR is correct", "percent_of_ar", expected["percent_of_ar"], weight=5, abs_tol=.00005),
                _weighted_numeric_criterion(row, f"override_schedule__{token}__retainage_ar", f"{customer} retainage exposure is correct", "retainage_ar", expected["retainage_ar"], weight=5),
                _weighted_numeric_criterion(row, f"override_schedule__{token}__nonretainage_ar", f"{customer} non-retainage exposure is correct", "nonretainage_ar", expected["nonretainage_ar"], weight=5),
                _exact_text_criterion(row, f"override_schedule__{token}__date", f"{customer} documented collection date is correct", "expected_collection_date", (expected["expected_collection_date"],), weight=5, category="source_interpretation"),
                _exact_text_criterion(row, f"override_schedule__{token}__confidence", f"{customer} documented collection confidence is correct", "collection_confidence", (expected["collection_confidence"],), weight=5, category="source_interpretation"),
                _weighted_numeric_criterion(row, f"override_schedule__{token}__july_timed_exposure", f"{customer} July-timed exposure is correct", "july_timed_exposure", expected["july_timed_exposure"], weight=5),
                _weighted_numeric_criterion(row, f"override_schedule__{token}__post_july_timed_exposure", f"{customer} post-July-timed exposure is correct", "post_july_timed_exposure", expected["post_july_timed_exposure"], weight=5),
            ]
        )
        open_ar = _number(_get(row, "open_ar"))
        retainage = _number(_get(row, "retainage_ar"))
        nonretainage = _number(_get(row, "nonretainage_ar"))
        july = _number(_get(row, "july_timed_exposure"))
        post_july = _number(_get(row, "post_july_timed_exposure"))
        row_bridge_matched = (
            None not in (open_ar, retainage, nonretainage)
            and abs(retainage + nonretainage - open_ar) <= .02
        )
        criteria.append(Criterion(f"override_schedule__{token}__exposure_bridge", f"{customer} retainage and non-retainage tie to open AR", row_bridge_matched, f"open_ar={open_ar!r}; retainage={retainage!r}; nonretainage={nonretainage!r}", category="controls", weight=3, semantic=False))
        row_timing_matched = (
            None not in (nonretainage, july, post_july)
            and abs(july + post_july - nonretainage) <= .02
        )
        criteria.append(Criterion(f"override_schedule__{token}__timing_bridge", f"{customer} July and post-July timing tie to non-retainage exposure", row_timing_matched, f"nonretainage={nonretainage!r}; july={july!r}; post_july={post_july!r}", category="controls", weight=3, semantic=False))
        schedule_open_total += open_ar or 0.0
        schedule_july_total += july or 0.0
        schedule_post_july_total += post_july or 0.0
        schedule_retainage_total += retainage or 0.0
        confidence = _normalize(_get(row, "collection_confidence"))
        if confidence in schedule_confidence_july:
            schedule_confidence_july[confidence] += july or 0.0

    reported_override_total = _number(_get(mapping, "override_population_total"))
    reported_july_total = _number(_get(mapping, "july_timed_override_exposure"))
    reported_post_july_total = _number(_get(mapping, "post_july_timed_override_exposure"))
    reported_retainage_total = _number(_get(mapping, "untimed_retainage_exposure"))
    reported_bridge_delta = _number(_get(mapping, "override_timing_bridge_delta"))
    schedule_total_matched = (
        reported_override_total is not None
        and abs(schedule_open_total - reported_override_total) <= .02
    )
    schedule_timing_matched = (
        reported_july_total is not None
        and reported_post_july_total is not None
        and reported_retainage_total is not None
        and abs(schedule_july_total - reported_july_total) <= .02
        and abs(schedule_post_july_total - reported_post_july_total) <= .02
        and abs(schedule_retainage_total - reported_retainage_total) <= .02
    )
    timing_bridge_matched = (
        None not in (reported_override_total, reported_july_total, reported_post_july_total, reported_retainage_total, reported_bridge_delta)
        and abs(
            reported_july_total
            + reported_post_july_total
            + reported_retainage_total
            + reported_bridge_delta
            - reported_override_total
        ) <= .02
    )
    reported_high_july = _number(_get(mapping, "high_confidence_july_exposure"))
    reported_medium_july = _number(_get(mapping, "medium_confidence_july_exposure"))
    reported_low_july = _number(_get(mapping, "low_confidence_july_exposure"))
    reported_below_high_july = _number(
        _get(mapping, "july_exposure_below_high_confidence")
    )
    reported_confidence_delta = _number(
        _get(mapping, "july_confidence_bridge_delta")
    )
    confidence_bridge_matched = (
        None
        not in (
            reported_july_total,
            reported_high_july,
            reported_medium_july,
            reported_low_july,
            reported_below_high_july,
            reported_confidence_delta,
        )
        and abs(schedule_confidence_july["high"] - reported_high_july) <= .02
        and abs(schedule_confidence_july["medium"] - reported_medium_july) <= .02
        and abs(schedule_confidence_july["low"] - reported_low_july) <= .02
        and abs(reported_medium_july + reported_low_july - reported_below_high_july)
        <= .02
        and abs(
            reported_high_july
            + reported_medium_july
            + reported_low_july
            - reported_july_total
            - reported_confidence_delta
        )
        <= .02
    )
    criteria.extend(
        [
            Criterion("control__override_schedule_total", "The five schedule rows tie to the reported override population", schedule_total_matched, f"schedule_total={schedule_open_total}; reported_total={reported_override_total!r}", category="controls", weight=5, semantic=False),
            Criterion("control__override_schedule_timing", "The schedule rows tie to the reported July, post-July, and held-retainage totals", schedule_timing_matched, f"schedule_july={schedule_july_total}; schedule_post_july={schedule_post_july_total}; schedule_retainage={schedule_retainage_total}; reported_july={reported_july_total!r}; reported_post_july={reported_post_july_total!r}; reported_retainage={reported_retainage_total!r}", category="controls", weight=5, semantic=False),
            Criterion("control__override_timing_bridge", "July exposure, post-July exposure, held retainage, and the bridge delta tie to the five-account population", timing_bridge_matched, f"population={reported_override_total!r}; july={reported_july_total!r}; post_july={reported_post_july_total!r}; retainage={reported_retainage_total!r}; delta={reported_bridge_delta!r}", category="controls", weight=10, semantic=False),
            Criterion("control__july_confidence_bridge", "High, Medium, and Low confidence schedule amounts reconcile to July-timed exposure and the below-High subtotal", confidence_bridge_matched, f"schedule={schedule_confidence_july}; reported_high={reported_high_july!r}; reported_medium={reported_medium_july!r}; reported_low={reported_low_july!r}; reported_below_high={reported_below_high_july!r}; july={reported_july_total!r}; delta={reported_confidence_delta!r}", category="controls", weight=10, semantic=False),
        ]
    )

    cash_handoff_totals = {
        key: 0.0
        for key in (
            "v9_july_gross_receipts",
            "v9_july_retainage_included",
            "v9_july_nonretainage_included",
            "june_30_additions_not_in_v9",
            "current_supported_july_nonretainage",
            "population_and_timing_adjustment",
            "net_july_receipt_correction",
        )
    }
    for expected in expected_cash_handoff:
        customer = expected["customer"]
        token = _normalize(customer).replace(" ", "_")
        row = customer_row(cash_handoff_rows, customer)
        criteria.extend(
            [
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__v9_july_gross", f"{customer} v9 gross July receipts are correct", "v9_july_gross_receipts", expected["v9_july_gross_receipts"], weight=10, category="reconciliation"),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__v9_july_retainage", f"{customer} retainage embedded in v9 July receipts is correct", "v9_july_retainage_included", expected["v9_july_retainage_included"], weight=10, category="reconciliation"),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__v9_july_nonretainage", f"{customer} v9 July non-retainage receipts are correct", "v9_july_nonretainage_included", expected["v9_july_nonretainage_included"], weight=5, category="reconciliation"),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__june_30_additions", f"{customer} June 30 population absent from v9 is correct", "june_30_additions_not_in_v9", expected["june_30_additions_not_in_v9"], weight=5, category="reconciliation"),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__current_supported_july", f"{customer} supported current July non-retainage receipts are correct", "current_supported_july_nonretainage", expected["current_supported_july_nonretainage"], weight=10),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__population_and_timing_adjustment", f"{customer} population-and-timing adjustment is correct", "population_and_timing_adjustment", expected["population_and_timing_adjustment"], weight=10, category="reconciliation"),
                _weighted_numeric_criterion(row, f"cash_handoff_schedule__{token}__net_july_correction", f"{customer} net correction to v9 July receipts is correct", "net_july_receipt_correction", expected["net_july_receipt_correction"], weight=10, category="decision_quality"),
            ]
        )
        gross = _number(_get(row, "v9_july_gross_receipts"))
        retainage = _number(_get(row, "v9_july_retainage_included"))
        nonretainage = _number(_get(row, "v9_july_nonretainage_included"))
        supported = _number(_get(row, "current_supported_july_nonretainage"))
        adjustment = _number(_get(row, "population_and_timing_adjustment"))
        correction = _number(_get(row, "net_july_receipt_correction"))
        row_bridge_matched = (
            None
            not in (
                gross,
                retainage,
                nonretainage,
                supported,
                adjustment,
                correction,
            )
            and abs(retainage + nonretainage - gross) <= .02
            and abs(nonretainage + adjustment - supported) <= .02
            and abs(gross + correction - supported) <= .02
        )
        criteria.append(
            Criterion(
                f"cash_handoff_schedule__{token}__bridge",
                f"{customer} v9 gross, retainage, population/timing adjustment, and current supported July receipts reconcile",
                row_bridge_matched,
                f"gross={gross!r}; retainage={retainage!r}; nonretainage={nonretainage!r}; supported={supported!r}; adjustment={adjustment!r}; correction={correction!r}",
                category="controls",
                weight=10,
                semantic=False,
            )
        )
        for key in cash_handoff_totals:
            cash_handoff_totals[key] += _number(_get(row, key)) or 0.0

    reported_cash_handoff_totals = {
        key: _number(_get(mapping, key)) for key in cash_handoff_totals
    }
    reported_handoff_delta = _number(_get(mapping, "cash_forecast_handoff_delta"))
    cash_handoff_control_matched = (
        all(
            reported_cash_handoff_totals[key] is not None
            and abs(
                cash_handoff_totals[key]
                - reported_cash_handoff_totals[key]
            )
            <= .02
            for key in cash_handoff_totals
        )
        and reported_handoff_delta is not None
        and abs(reported_handoff_delta) <= .02
        and reported_july_total is not None
        and abs(
            reported_cash_handoff_totals["current_supported_july_nonretainage"]
            - reported_july_total
        )
        <= .02
    )
    criteria.append(
        Criterion(
            "control__cash_forecast_handoff",
            "The five handoff rows tie to every summary amount, the current July override total, and a zero handoff delta",
            cash_handoff_control_matched,
            f"schedule_totals={cash_handoff_totals!r}; reported_totals={reported_cash_handoff_totals!r}; handoff_delta={reported_handoff_delta!r}; current_july={reported_july_total!r}",
            category="controls",
            weight=10,
            semantic=False,
        )
    )

    expected_actions = {row["customer"]: row for row in gold["collection_action_queue"]}
    for customer in [row["customer"] for row in expected_schedule]:
        row = customer_row(action_rows, customer)
        token = _normalize(customer).replace(" ", "_")
        evidence = _normalize(_get(row, "evidence_required"))
        owner = _normalize(_get(row, "action_owner"))
        next_action = _normalize(_get(row, "next_action"))
        if customer == "Columbia Biologics":
            evidence_matched = "validation" in evidence and "accept" in evidence and any(value in evidence for value in ("close out", "closeout", "support"))
            owner_matched = "controller" in owner
            next_action_matched = any(value in next_action for value in ("approve", "release", "move")) and any(value in next_action for value in ("base forecast", "base cash")) and any(value in next_action for value in ("accept", "evidence"))
        elif customer == "Cascade Health":
            evidence_matched = "signed" in evidence and "transmittal" in evidence and "release" in evidence
            owner_matched = "project account" in owner
            next_action_matched = "transmittal" in next_action and "release" in next_action and any(value in next_action for value in ("obtain", "attach", "receive"))
        elif customer == "Redmond Unified":
            evidence_matched = "board" in evidence and "calendar" in evidence and any(value in evidence for value in ("warrant", "july 29", "2026 07 29"))
            owner_matched = "project account" in owner
            next_action_matched = "calendar" in next_action and "warrant" in next_action and any(value in next_action for value in ("attach", "confirm"))
        elif customer == "Eastbank Data":
            evidence_matched = "waiver" in evidence and "upload" in evidence
            owner_matched = "project manager" in owner or re.search(r"\bpm\b", owner) is not None
            next_action_matched = "waiver" in next_action and any(value in next_action for value in ("july 14", "2026 07 14")) and any(value in next_action for value in ("confirm", "attach", "upload"))
        else:
            evidence_matched = "remittance" in evidence and any(value in evidence for value in ("ach", "release"))
            owner_matched = "project account" in owner
            next_action_matched = "remittance" in next_action and any(value in next_action for value in ("july 10", "2026 07 10")) and any(value in next_action for value in ("confirm", "attach"))
        expected_action = expected_actions[customer]
        criteria.extend(
            [
                Criterion(f"action_queue__{token}__evidence", f"{customer} required evidence is supported by the collection notes", evidence_matched, f"evidence_required={_get(row, 'evidence_required')!r}; reference={expected_action['evidence_required']!r}", category="source_interpretation", weight=5, semantic=False),
                Criterion(f"action_queue__{token}__owner", f"{customer} has the primary accountable owner supported by the governance notes", owner_matched, f"action_owner={_get(row, 'action_owner')!r}; reference={expected_action['action_owner']!r}", category="decision", weight=3, semantic=False),
                Criterion(f"action_queue__{token}__next_action", f"{customer} next action follows the documented evidence and timing", next_action_matched, f"next_action={_get(row, 'next_action')!r}; reference={expected_action['next_action']!r}", category="decision", weight=5, semantic=False),
            ]
        )

    criteria.extend(
        [
            Criterion("format__single_json_object", "The final response contains only the requested JSON object", _is_single_json_object(answer), f"single_json_object={_is_single_json_object(answer)}", category="formatting", weight=1, semantic=False),
            Criterion("format__exact_keys", "The JSON object contains exactly the requested keys", set(mapping) == expected_keys, f"actual_keys={sorted(mapping)}; expected_keys={sorted(expected_keys)}", category="formatting", weight=1, semantic=False),
        ]
    )
    return criteria


