    oregon_availability = availability_cases["oregon_state_only"]
    funding_action_gold = liquidity_gold["funding_action_threshold"]
    funding_action_mapping = liquidity_mapping.get("funding_action_threshold")
    funding_action_mapping = (
        funding_action_mapping if isinstance(funding_action_mapping, dict) else {}
    )
    funding_action_text = (
        json.dumps(funding_action_mapping, ensure_ascii=False)
        if funding_action_mapping
        else context(
            "cutoff",
            "erosion",
            "eligible AR",
            "minimum refreshed",
            "funding gap",
            "stop/go",
        )
    )

    def month_day(haystack: str, month: str, day: int) -> bool:
        month_number = {"June": 6, "July": 7, "August": 8}[month]
        return has_any(
            haystack,
            f"{month} {day}",
            f"{month[:3]} {day}",
            f"{month_number}/{day}",
        )

