        def follow_up_matches(actual: Any, expected: str) -> bool:
            normalized = _normalize(actual)
            tokens = normalized.split()
            token_set = set(tokens)
            if token_set & {
                "not", "no", "avoid", "reject", "exclude", "without",
                "never", "skip", "omit",
            } or any(
                phrase in normalized
                for phrase in (
                    "don t", "doesn t", "isn t", "shouldn t", "mustn t",
                    "can t", "cannot",
                )
            ):
                return False
            if expected == "recovery_plan_priority":
                return "recovery" in token_set and any(
                    token in token_set for token in ("plan", "priority", "review")
                )
            if expected == "worsening_trend_watch":
                return "trend" in token_set and (
                    "watch" in token_set
                    or any(token.startswith(("worsen", "increas")) for token in tokens)
                )
            if expected == "highest_intensity_root_cause_review":
                return "root" in token_set and "cause" in token_set
            return False

        def tied_control_matches(actual: Any) -> bool:
            normalized = _normalize(actual)
            return any(
                phrase in normalized
                for phrase in (
                    "tied", "reconciled", "zero difference", "zero delta",
                    "no difference", "no variance",
                )
            )

        def portfolio_follow_up_matches(actual: Any) -> bool:
            normalized = _normalize(actual)
            tokens = set(normalized.split())
            return (
                "root" in tokens
                and "cause" in tokens
                and any(token.startswith("review") for token in tokens)
                and any(
                    token.startswith("intens") or token == "portfolio"
                    for token in tokens
                )
            )

        def deck_action_matches(actual: Any) -> bool:
            normalized = _normalize(actual)
            return (
                any(token in normalized.split() for token in ("replace", "update"))
                and "final" in normalized
                and "approved" in normalized
                and any(value in normalized for value in ("4464 97", "q2 hours"))
            )

        def cost_treatment_matches(actual: Any) -> bool:
            normalized = _normalize(actual)
            not_posted = bool(
                re.search(r"\b(?:do not|not|never)\s+post\b", normalized)
            )
            not_added = bool(
                re.search(r"\b(?:do not|not|never)\s+add\b", normalized)
                or re.search(
                    r"\b(?:do not|not|never)\s+post(?:\s+it)?\s+(?:or|and)\s+add\b",
                    normalized,
                )
            )
            return (
                (
                    "sensitivity" in normalized
                    and not_posted
                    and not_added
                    and "eac" in normalized
                )
                or (
                    "recorded" in normalized
                    and "job cost" in normalized
                    and any(term in normalized for term in ("already", "included"))
                )
            )

