        def _date_matches(value: Any, iso_date: str) -> bool:
            normalized = _normalize(value)
            year, month, day = iso_date.split("-")
            month_names = {
                "01": ("january", "jan"), "02": ("february", "feb"),
                "03": ("march", "mar"), "04": ("april", "apr"),
                "05": ("may",), "06": ("june", "jun"),
                "07": ("july", "jul"), "08": ("august", "aug"),
                "09": ("september", "sep"), "10": ("october", "oct"),
                "11": ("november", "nov"), "12": ("december", "dec"),
            }
            return normalized == _normalize(iso_date) or (
                year in normalized
                and str(int(day)) in normalized.split()
                and any(name in normalized for name in month_names[month])
            )

