        def cash_relation(
            criterion_id: str,
            description: str,
            left: str,
            right: float | None,
        ) -> Criterion:
            return Criterion(
                criterion_id,
                description,
                right is not None and _close(cash_numbers[left], right),
                f"actual={cash_numbers[left]!r}; calculated={right!r}",
                category="reconciliation",
                weight=10,
                semantic=False,
            )

        def cash_sum(*keys: str) -> float | None:
            values = [cash_numbers[key] for key in keys]
            return None if any(value is None for value in values) else sum(values)  # type: ignore[arg-type]

        def cash_difference(left: str, right: str) -> float | None:
            values = cash_numbers[left], cash_numbers[right]
            return None if any(value is None for value in values) else values[0] - values[1]  # type: ignore[operator]

